  "Developments Underway": {"de":"Laufende Entwicklungen","ru":"Проекты в разработке","ka":"მიმდინარე განვითარებები","tr":"Devam eden projeler","ar":"مشاريع قيد التطوير"},
  "Markets Served": {"de":"Bediente Märkte","ru":"Обслуживаемые рынки","ka":"მომსახურე ბაზრები","tr":"Hizmet verilen pazarlar","ar":"الأسواق المخدومة"},
  "Status: Legacy portfolio — realized": {"de":"Status: Legacy-Portfolio — realisiert","ru":"Статус: наследие портфеля — реализовано","ka":"სტატუსი: მემკვიდრეობითი პორტფელი — რეალიზებული","tr":"Durum: Miras portföy — gerçekleşti","ar":"الحالة: محفظة إرثية — مُنجَزة"},
